import sys; sys.path.insert(0, '_tools'); from spec import enrich
enrich('la-paz-para-este-tiempo-iii', 'C',
 [dict(t=1303, e=1358, titulo='La pared intermedia se cae hoy', txt='Fíjese que dice: «Porque él mismo es nuestra paz». Quiere decir que si el Señor Jesucristo derrama de su paz, ¿qué tenemos que hacer? Agarrar esa paz, para que lo que él derramó nosotros seamos como él. «Porque él mismo es nuestra paz, quien de ambos pueblos hizo uno […]». Y el pueblo de Dios es usted y yo y todos los que quieran entrar a él. Entonces dice «la pared intermedia». Había una pared; hoy se cae. Toda pared que se haya levantado entre ti, entre tu vida y Dios, se cae hoy.'),
  dict(t=2187, e=2262, titulo='Dios guarda el corazón y los pensamientos', txt='Filipenses 4:7 dice: «Y la paz de Dios guardará vuestros corazones». Entonces, una de las cosas para saber si tenemos la paz de Dios es que estén guardados nuestro corazón y nuestros pensamientos. Dios le tiene que guardar su corazón y sus pensamientos, porque a veces los pensamientos aceleran el corazón. A veces los pensamientos estresan su corazón, y usted está con el corazón a mil porque no confiamos en Dios. Cuando sean malos pensamientos, no son de Dios: es el enemigo trabajando en su mente. Por eso usted tiene que creer que Dios le va a guardar su corazón.'),
  dict(t=3707, e=3765, titulo='Profetízales para que esos huesos vivan', txt='«Huesos, ¿vivirán estos huesos?». Jeremías, solo tú lo sabes. Profetízales para que esos huesos vivan. Y adentro del hueso está el espíritu, y hoy esta noche le vengo profetizando a tus huesos para que vivan. Póngase de pie, hermano. Aquí está la clave; aquí está lo que vamos a creer hoy. Siento una gran unción. […] Como profeta de Dios le vengo profetizando a los huesos secos, a los huesos que no tienen vida, para que cada hueso tome su lugar.')],
 [dict(t=1118, txt='Esa fe que mueve montañas es la que Dios está derramando para tu vida hoy.'),
  dict(t=2819, txt='Cuando hay paz, cuando hay agradecimiento, el Señor percibe eso como un olor agradable.'),
  dict(t=3340, txt='Te vas a dar cuenta que el único que te puede dar paz en tu corazón soy yo.')],
 ['Si Cristo es nuestra paz y derriba la pared intermedia, ¿qué pared sientes que todavía hay entre tú y Dios?',
  '¿Cómo reconoces que Dios está guardando tu corazón y tus pensamientos, y qué haces cuando llegan los malos pensamientos?',
  '¿De qué cosa seca en tu vida o en tu familia necesitas hoy creer que Dios puede dar vida?'])
